/**
 * @/types.ts
 * ARCHITECTURAL NOTE: This file is the single source of truth for shared types across the frontend.
 * As we transition to a federated GraphQL architecture, these types are manually aligned with the BFF's
 * `graphql.schema.gql`. In a production CI/CD pipeline, these types would be auto-generated by a tool
 * like GraphQL Code Generator to ensure they are always in sync with the supergraph schema.
 */

// ================================================================================================
// CORE ENUMS & CLIENT-SIDE STATE
// ================================================================================================

/**
 * Defines all primary views/pages within the application for client-side navigation and routing.
 * This is a client-side concern and is not part of the GraphQL schema.
 */
export enum View {
  Dashboard = 'dashboard',
  Transactions = 'transactions',
  SendMoney = 'send-money',
  Budgets = 'budgets',
  Investments = 'investments',
  AIAdvisor = 'ai-advisor',
  QuantumWeaver = 'quantum-weaver',
  AIAdStudio = 'ai-ad-studio',
  Crypto = 'crypto',
  Goals = 'goals',
  Marketplace = 'marketplace',
  Security = 'security',
  Personalization = 'personalization',
  CardCustomization = 'card-customization',
  OpenBanking = 'open-banking',
  CorporateCommand = 'corporate-command',
  APIIntegration = 'api-integration',
  Rewards = 'rewards',
  CreditHealth = 'credit-health',
  Settings = 'settings',
  FinancialDemocracy = 'financial-democracy',
  TheVision = 'the-vision',
}

/**
 * Defines the types of dynamic background illusions available for personalization.
 * This is a client-side UI state type.
 */
export type IllusionType = 'none' | 'aurora';

// ================================================================================================
// GRAPHQL SCHEMA ENUMS
// These enums mirror the enums defined in the GraphQL schema.
// ================================================================================================

export enum TransactionType {
  INCOME = 'INCOME',
  EXPENSE = 'EXPENSE',
}

export enum RewardType {
  CASHBACK = 'CASHBACK',
  GIFTCARD = 'GIFTCARD',
  IMPACT = 'IMPACT',
}

export enum CreditRating {
  EXCELLENT = 'EXCELLENT',
  GOOD = 'GOOD',
  FAIR = 'FAIR',
  POOR = 'POOR',
}

export enum APIProvider {
  Plaid = 'Plaid',
  Stripe = 'Stripe',
  Marqeta = 'Marqeta',
  ModernTreasury = 'ModernTreasury',
  GoogleGemini = 'GoogleGemini',
}

export enum APIStatusType {
  Operational = 'Operational',
  DegradedPerformance = 'DegradedPerformance',
  PartialOutage = 'PartialOutage',
  MajorOutage = 'MajorOutage',
}

export enum WeaverStage {
  Pitch = 'Pitch',
  Analysis = 'Analysis',
  Test = 'Test',
  FinalReview = 'FinalReview',
  Approved = 'Approved',
  Error = 'Error',
}

// ================================================================================================
// GRAPHQL SUPERGRAPH TYPES
// These interfaces represent the shape of data queried from the federated GraphQL endpoint.
// ================================================================================================

export interface Transaction {
  __typename?: 'Transaction';
  id: string;
  type: TransactionType;
  category: string;
  description: string;
  amount: number;
  date: string; // Corresponds to the 'Date' scalar
  carbonFootprint?: number | null;
}

export interface Asset {
  __typename?: 'Asset';
  name: string;
  value: number;
  color: string;
  esgRating?: number | null;
  description?: string | null;
  performanceYTD?: number | null;
}

export interface AIInsightChartData {
  __typename?: 'AIInsightChartData';
  name: string;
  value: number;
}

export interface AIInsight {
  __typename?: 'AIInsight';
  id: string;
  title: string;
  description: string;
  urgency: string;
  chartData?: (AIInsightChartData | null)[] | null;
}

export interface BudgetCategory {
  __typename?: 'BudgetCategory';
  id: string;
  name: string;
  limit: number;
  spent: number;
  color: string;
}

export interface GamificationState {
  __typename?: 'GamificationState';
  score: number;
  level: number;
  levelName: string;
  progress: number;
  credits: number;
}

export interface Subscription {
  __typename?: 'Subscription';
  id: string;
  name: string;
  amount: number;
  nextPayment: string; // Corresponds to the 'Date' scalar
  iconName: string;
}

export interface CreditScore {
  __typename?: 'CreditScore';
  score: number;
  change: number;
  rating: CreditRating;
}

export interface CreditFactor {
  __typename?: 'CreditFactor';
  name: string;
  status: CreditRating;
  description: string;
}

export interface CreditHealth {
  __typename?: 'CreditHealth';
  score: CreditScore;
  factors: CreditFactor[];
  aiTip?: string | null;
}

export interface UpcomingBill {
  __typename?: 'UpcomingBill';
  id: string;
  name: string;
  amount: number;
  dueDate: string; // Corresponds to the 'Date' scalar
}

export interface AIGoalPlanStep {
  __typename?: 'AIGoalPlanStep';
  title: string;
  description: string;
  category: string;
}

export interface AIGoalPlan {
  __typename?: 'AIGoalPlan';
  feasibilitySummary: string;
  monthlyContribution: number;
  steps: AIGoalPlanStep[];
}

export interface Contribution {
  __typename?: 'Contribution';
  id: string;
  amount: number;
  date: string; // Corresponds to the 'Date' scalar
  type: string;
}

export interface FinancialGoal {
  __typename?: 'FinancialGoal';
  id: string;
  name: string;
  targetAmount: number;
  targetDate: string; // Corresponds to the 'Date' scalar
  currentAmount: number;
  iconName: string;
  plan?: AIGoalPlan | null;
  contributions?: (Contribution | null)[] | null;
}

export interface CryptoAsset {
  __typename?: 'CryptoAsset';
  ticker: string;
  name: string;
  value: number;
  amount: number;
  color: string;
}

export interface NFTAsset {
  __typename?: 'NFTAsset';
  id: string;
  name: string;
  imageUrl: string;
  contractAddress: string;
}

export interface CryptoPortfolio {
  __typename?: 'CryptoPortfolio';
  assets: CryptoAsset[];
  nfts: NFTAsset[];
}

export interface CorporateCardControls {
  __typename?: 'CorporateCardControls';
  atm: boolean;
  contactless: boolean;
  online: boolean;
  monthlyLimit: number;
}

export interface CorporateCard {
  __typename?: 'CorporateCard';
  id: string;
  holderName: string;
  cardNumberMask: string;
  status: string;
  frozen: boolean;
  controls: CorporateCardControls;
}

export interface CorporateTransaction {
  __typename?: 'CorporateTransaction';
  id: string;
  cardId: string;
  holderName: string;
  merchant: string;
  amount: number;
  status: string;
  timestamp: string;
}

export interface CorporateData {
  __typename?: 'CorporateData';
  cards: CorporateCard[];
  transactions: CorporateTransaction[];
  aiAnomalyInsight?: string | null;
}

export interface RewardPoints {
  __typename?: 'RewardPoints';
  balance: number;
  currency: string;
}

export interface RewardItem {
  __typename?: 'RewardItem';
  id: string;
  name: string;
  cost: number;
  type: RewardType;
  description: string;
  iconName: string;
}

export interface Rewards {
  __typename?: 'Rewards';
  points: RewardPoints;
  items: RewardItem[];
}

export interface Notification {
  __typename?: 'Notification';
  id: string;
  message: string;
  timestamp: string;
  read: boolean;
  view?: string | null;
}

export interface APIStatus {
  __typename?: 'APIStatus';
  provider: APIProvider;
  status: APIStatusType;
  responseTime: number;
}

/**
 * Represents the main data payload for the dashboard, combining multiple data sources.
 * This is the primary query for hydrating the application's main view.
 */
export interface UserData {
  __typename?: 'UserData';
  transactions: Transaction[];
  assets: Asset[];
  aiInsights: AIInsight[];
  budgets: BudgetCategory[];
  gamification: GamificationState;
  subscriptions: Subscription[];
  upcomingBills: UpcomingBill[];
  financialGoals: FinancialGoal[];
  cryptoPortfolio: CryptoPortfolio;
  corporateData: CorporateData;
  creditHealth: CreditHealth;
  rewards: Rewards;
  notifications: Notification[];
  apiStatus: APIStatus[];
}

// ================================================================================================
// LEGACY & DEPRECATED TYPES
// These types were used in previous versions and are kept for reference during the transition.
// They will be removed once all components are migrated to use the new GraphQL-aligned types.
// ================================================================================================

/** @deprecated Use FinancialGoal instead. */
export interface SavingsGoal {
  id: string;
  name: string;
  target: number;
  saved: number;
  iconName: string;
}

/** @deprecated Use the `transactions` field in the `UserData` query. */
export interface RecentTransactions extends Transaction {}

/** @deprecated Use the `assets` field from the `UserData` query and calculate totals on the client if needed. */
export interface InvestmentPortfolio {
  assets: Asset[];
  totalValue: number;
  weightedPerformance: number;
}
